      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "How does the SARS-CoV-2 reinfection rate change over time? The global evidence from systematic review and meta-analysis",
      "reason": "The title explicitly identifies the report as a systematic review (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "How does the SARS-CoV-2 reinfection rate change over time? The global evidence from systematic review and meta-analysis",
      "reason": "The title conveys the review question/objective: the SARS-CoV-2 reinfection rate and its change over time, in a global population."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The global evidence from systematic review and meta-analysis",
